import{_ as o,c as e,o as t,a4 as n}from"./chunks/framework.BYxathSa.js";const h=JSON.parse('{"title":"Q12：原型与原型链是什么？","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q12.md","filePath":"frontend/q12.md","lastUpdated":null}'),s={name:"frontend/q12.md"},a=n(`<h1 id="q12-原型与原型链是什么" tabindex="-1">Q12：原型与原型链是什么？ <a class="header-anchor" href="#q12-原型与原型链是什么" aria-label="Permalink to &quot;Q12：原型与原型链是什么？&quot;">​</a></h1><ul><li><strong>原型对象</strong>：每一个函数在创建时都会有一个 <code>prototype</code> 属性，指向该函数（作为构造函数）创建的所有实例对象共享的<em>原型对象</em>。</li><li><strong><code>__proto__</code>（隐式原型）</strong>：每个对象（除 null 外）都有 <code>__proto__</code> 属性，指向它构造函数的 <code>prototype</code>。<br> 实例的 <code>__proto__ === 构造函数.prototype</code>。</li><li><strong>原型链</strong>：当访问一个对象的属性或方法时，如果自身没有，就会沿着 <code>__proto__</code> 向上查找，直到找到或到达 <code>null</code>。这条链路就叫原型链。</li><li><strong>终点</strong>：<code>Object.prototype.__proto__ === null</code>。</li><li><strong>作用</strong>：实现了 JavaScript 的继承机制。所有对象都继承了 <code>Object.prototype</code> 上的方法（如 <code>toString()</code>），数组实例则共享 <code>Array.prototype</code> 上的方法。</li></ul><p><strong>经典图景</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>function Person() {}</span></span>
<span class="line"><span>let p = new Person();</span></span>
<span class="line"><span>// p.__proto__ === Person.prototype</span></span>
<span class="line"><span>// Person.prototype.__proto__ === Object.prototype</span></span>
<span class="line"><span>// Object.prototype.__proto__ === null</span></span></code></pre></div>`,4),p=[a];function r(c,_,l,d,i,g){return t(),e("div",null,p)}const m=o(s,[["render",r]]);export{h as __pageData,m as default};
